      read_first?: ReadFirstRaw[];
      stats?: {
        t?: unknown;
        estimated_tokens?: unknown;
        tokens?: unknown;
        b?: unknown;
        token_budget?: unknown;
        budget?: unknown;
        local_work?: unknown;
        local?: unknown;
